message.content:
{
  "title": "The Rescue of the Lightbearer",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates with rusted iron portcullis, overgrown with thorny vines, under a blood-red sunset sky.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior"]
    },
    {
      "scene_number": 2,
      "caption": "They slip past the armored patrol.",
      "visual_description": "A squad of black-armored guards marches along a cracked avenue, their torches casting long shadows.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Armored Patrol Guard"]
    },
    {
      "scene_number": 3,
      "caption": "Frightened townspeople whisper warnings.",
      "visual_description": "Huddled figures in tattered cloaks point toward a towering black spire, their faces pale with fear.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Townspeople"]
    },
    {
      "scene_number": 4,
      "caption": "A rumored dragon circles overhead.",
      "visual_description": "A massive winged silhouette spirals down through the smoke, its scales glinting like embers.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Dragon"]
    },
    {
      "scene_number": 5,
      "caption": "They find old royal banners in a collapsed hall.",
      "visual_description": "Tattered gold-and-crimson banners hang from a broken ceiling, faded crests of a lion and star.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower beckons with eerie light.",
      "visual_description": "A crooked tower emitting a pulsing green glow, its windows shaped like screaming faces.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior"]
    },
    {
      "scene_number": 7,
      "caption": "Elara disables a magical door.",
      "visual_description": "A door covered in runes that glow and shift; Elara traces counter-runes with her staff.",
      "characters": ["Elara the Mage", "Aric the Ranger", "Kael the Warrior"]
    },
    {
      "scene_number": 8,
      "caption": "Aric spots the princess's signal.",
      "visual_description": "A small mirror flash from a high window in the cursed tower.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Princess Lyra"]
    },
    {
      "scene_number": 9,
      "caption": "They climb the tower's spiral stairs.",
      "visual_description": "Narrow, uneven steps slick with moss, each landing holding a dusty skeleton.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior"]
    },
    {
      "scene_number": 10,
      "caption": "Kael breaks down the prison door.",
      "visual_description": "A heavy iron door with a magical lock; Kael's shoulder slams against it as runes flare.",
      "characters": ["Kael the Warrior", "Aric the Ranger", "Elara the Mage", "Princess Lyra"]
    },
    {
      "scene_number": 11,
      "caption": "The princess is freed from her chains.",
      "visual_description": "Lyra stands in a circle of faint light, silver chains around her wrists falling away.",
      "characters": ["Princess Lyra", "Aric the Ranger", "Elara the Mage", "Kael the Warrior"]
    },
    {
      "scene_number": 12,
      "caption": "The dragon lands on the tower roof.",
      "visual_description": "The dragon claws the battlements, its hot breath steaming the stone.",
      "characters": ["Dragon", "Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Princess Lyra"]
    },
    {
      "scene_number": 13,
      "caption": "Elara casts a blinding spell to distract it.",
      "visual_description": "A brilliant white orb erupts from Elara's hands, forcing the dragon to recoil.",
      "characters": ["Elara the Mage", "Dragon", "Aric the Ranger", "Kael the Warrior", "Princess Lyra"]
    },
    {
      "scene_number": 14,
      "caption": "They race down the tower as it crumbles.",
      "visual_description": "Stones fall from above; the staircase cracks under their feet.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Princess Lyra"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols block the main street.",
      "visual_description": "A line of guards with pikes stands across the rubble-strewn road.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Princess Lyra", "Armored Patrol Guard"]
    },
    {
      "scene_number": 16,
      "caption": "They fight through to the bridge.",
      "visual_description": "Clashing swords and spells as the group pushes forward under a hail of arrows.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Princess Lyra", "Armored Patrol Guard"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to collapse behind them.",
      "visual_description": "A stone bridge arching over a chasm; blocks tumble into the dark water below as they sprint.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Princess Lyra"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the forest as dawn breaks.",
      "visual_description": "The group emerges from the city's shadow into golden morning light, the ruined city behind them.",
      "characters": ["Aric the Ranger", "Elara the Mage", "Kael the Warrior", "Princess Lyra"]
    }
  ]
}

